import { generateText } from "ai";
import { NextResponse } from "next/server";
import { z } from "zod";
import { verifyTurnstile } from "@/lib/abuse/turnstile";
import { getRequestIdentity, type RequestIdentity } from "@/lib/auth/identity";
import { transformOperationKey } from "@/lib/billing/operation-key";
import { commitReservation, grantGuestPromoCredits, initializeCreditAccount, releaseReservation, reserveCredits } from "@/lib/billing/server";
import { BillingDomainError } from "@/lib/billing/types";
import { countWords, MAX_REWRITE_WORDS } from "@/lib/product-contract";
import { planSanitizationJob, SanitizationContractError } from "@/lib/sanitization";
import { ApiRequestError, apiError, apiOk, parseJson, requestContext, retryAfter } from "@/lib/server/api";
import { logEvent, requestSubjectKey } from "@/lib/server/observability";
import { configuredLimit, consumeRateLimit } from "@/lib/server/rate-limit";
import { applyAuthCookies, createClient, type AuthCookie } from "@/lib/supabase/server";
import {
  chunkProtectedText,
  prepareProtectedText,
  TRANSFORM_INTENSITIES,
  TRANSFORM_MODES,
  TRANSFORM_PURPOSES,
  TRANSFORM_SYSTEM,
  transformPrompt,
  unavailableTextWatermarkVerifier,
  validateTransformedDraft,
} from "@/lib/transform";
import type { TransformIntensity, TransformMode, TransformPurpose, TransformResult } from "@/lib/transform";

export const runtime = "nodejs";
const DEFAULT_MODEL = "mistral/mistral-medium-3.5";
const MAX_ATTEMPTS = 2;
const PREVIEW_RELEASE_SMOKE_MARKER = "[[PROVENANCE_PREVIEW_RELEASE_SMOKE]]";

export const transformRequestSchema = z.object({
  operationId: z.string().uuid(),
  text: z.string().trim().min(20).max(250_000),
  mode: z.enum(TRANSFORM_MODES),
  intensity: z.enum(TRANSFORM_INTENSITIES).default("balanced"),
  purpose: z.enum(TRANSFORM_PURPOSES).default("general"),
  challengeToken: z.string().max(2048).optional(),
});

function wordBucket(words: number) {
  if (words <= 250) return "<=250";
  if (words <= 1_000) return "251-1000";
  if (words <= 4_000) return "1001-4000";
  return "4001-8000";
}
function charBucket(chars: number) {
  if (chars <= 2_000) return "<=2K";
  if (chars <= 10_000) return "2K-10K";
  if (chars <= 50_000) return "10K-50K";
  return ">50K";
}

async function generateAttempt(
  protectedText: string,
  mode: TransformMode,
  intensity: TransformIntensity,
  purpose: TransformPurpose,
  model: string,
  retryFeedback?: string,
) {
  const outputs: string[] = [];
  for (const chunk of chunkProtectedText(protectedText)) {
    const { text } = await generateText({
      model,
      system: TRANSFORM_SYSTEM,
      prompt: transformPrompt(chunk, mode, intensity, purpose, retryFeedback),
      temperature: intensity === "light" ? 0.2 : intensity === "strong" ? 0.4 : 0.3,
    });
    outputs.push(text.trim());
  }
  return outputs.join("\n\n");
}

function billingError(context: ReturnType<typeof requestContext>, error: BillingDomainError) {
  if (error.code === "insufficient_credits") return apiError(context, error.code, "Not enough credits are available for this edit.", 402);
  if (error.code === "rate_limited" || error.code === "daily_credit_limit") {
    return apiError(context, error.code, error.code === "rate_limited" ? "Too many editing requests were started recently." : "The daily editing-credit safety limit has been reached.", 429, retryAfter(60));
  }
  if (error.code === "operation_conflict") return apiError(context, error.code, "This edit operation has already been used.", 409);
  return apiError(context, "billing_unavailable", "Billing is not available.", 503);
}

async function ensureIdentityAfterChallenge(request: Request, authCookies: AuthCookie[]) {
  let identity: RequestIdentity | null;
  try {
    identity = await getRequestIdentity();
  } catch {
    throw new Error("account_unavailable");
  }
  if (identity) {
    if (identity.isAnonymous) await grantGuestPromoCredits(identity.userId);
    return identity;
  }

  const supabase = await createClient((cookiesToSet) => authCookies.push(...cookiesToSet));
  const { data, error } = await supabase.auth.signInAnonymously();
  if (error || !data.user) throw new Error("account_unavailable");
  await initializeCreditAccount(data.user.id);
  await grantGuestPromoCredits(data.user.id);
  logEvent("guest_session_created_for_transform", {
    requestId: request.headers.get("x-request-id") ?? undefined,
    userIdHash: requestSubjectKey(request, data.user.id),
  });
  return {
    userId: data.user.id,
    isAnonymous: true,
    email: null,
    emailVerified: false,
  } satisfies RequestIdentity;
}

export async function POST(request: Request) {
  const context = requestContext(request, "/api/transform");

  let parsed: z.infer<typeof transformRequestSchema>;
  try {
    parsed = await parseJson(request, transformRequestSchema, 300_000);
  } catch (error) {
    return error instanceof ApiRequestError
      ? apiError(context, error.code, error.message, error.status)
      : apiError(context, "invalid_request", "Request is invalid.", 400);
  }

  let job;
  try {
    job = planSanitizationJob({ kind: "text", intent: "rewrite", text: parsed.text });
  } catch (error) {
    if (error instanceof SanitizationContractError && error.code === "rewrite_too_large") {
      return apiError(context, "rewrite_too_large", `Semantic editing accepts at most ${MAX_REWRITE_WORDS.toLocaleString("en-US")} words per operation. Split larger documents into parts.`, 413);
    }
    return apiError(context, "invalid_request", "The rewrite job does not satisfy the product contract.", 400);
  }

  const preAuthSubject = requestSubjectKey(request);
  const preAuthBurst = consumeRateLimit("transform-attempt", preAuthSubject, configuredLimit("RATE_LIMIT_TRANSFORM_PER_MINUTE", 8), 60_000);
  if (!preAuthBurst.allowed) return apiError(context, "rate_limited", "Too many edit requests. Try again shortly.", 429, retryAfter(preAuthBurst.retryAfterSeconds));

  const challenge = await verifyTurnstile(parsed.challengeToken, "transform");
  if (!challenge.ok) {
    logEvent("bot_challenge_failed", { requestId: context.requestId, route: context.route, subjectHash: preAuthSubject, reason: challenge.reason ?? "unknown" });
    return apiError(
      context,
      challenge.reason === "not_configured" ? "bot_protection_unavailable" : "bot_challenge_failed",
      challenge.reason === "not_configured" ? "Bot protection is not configured." : "Bot verification is required.",
      challenge.reason === "not_configured" ? 503 : 403,
    );
  }

  const authCookies: AuthCookie[] = [];
  const respond = (response: NextResponse) => authCookies.length ? applyAuthCookies(response, authCookies) : response;
  let identity: RequestIdentity;
  try {
    identity = await ensureIdentityAfterChallenge(request, authCookies);
  } catch {
    return respond(apiError(context, "account_unavailable", "Account service is not available.", 503));
  }

  const subject = requestSubjectKey(request, identity.userId);
  const burst = consumeRateLimit("transform-account", subject, configuredLimit("RATE_LIMIT_TRANSFORM_PER_MINUTE", 8), 60_000);
  if (!burst.allowed) return respond(apiError(context, "rate_limited", "Too many edit requests. Try again shortly.", 429, retryAfter(burst.retryAfterSeconds)));

  const cost = job.credits;
  const sourceWords = countWords(parsed.text);
  logEvent("transform_request", {
    requestId: context.requestId,
    userIdHash: subject,
    operationId: parsed.operationId,
    sourceSizeBucket: charBucket(parsed.text.length),
    sourceWordBucket: wordBucket(sourceWords),
    credits: cost,
    mode: parsed.mode,
    intensity: parsed.intensity,
    purpose: parsed.purpose,
  });

  let reservationId: string;
  try {
    const reservation = await reserveCredits(identity.userId, transformOperationKey(parsed.operationId), cost);
    reservationId = reservation.reservationId;
    if (!reservation.created || reservation.status !== "reserved") {
      return respond(apiError(context, "operation_conflict", "This edit operation is already in progress or complete.", 409));
    }
    logEvent("credit_reservation", { requestId: context.requestId, userIdHash: subject, operationId: parsed.operationId, credits: cost });
  } catch (error) {
    if (error instanceof BillingDomainError) return respond(billingError(context, error));
    return respond(apiError(context, "billing_unavailable", "Billing is not available.", 503));
  }

  const prepared = prepareProtectedText(parsed.text);
  const model = process.env.TRANSFORM_MODEL ?? DEFAULT_MODEL;
  const injectPreviewFailure = process.env.VERCEL_ENV === "preview" && parsed.text.includes(PREVIEW_RELEASE_SMOKE_MARKER);
  let retryFeedback: string | undefined;

  try {
    if (injectPreviewFailure) throw new Error("controlled_preview_release_smoke");
    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
      const draft = await generateAttempt(prepared.protectedText, parsed.mode, parsed.intensity, parsed.purpose, model, retryFeedback);
      const validation = validateTransformedDraft(prepared, draft, parsed.mode);
      if (validation.ok && validation.restoredText) {
        const balance = await commitReservation(identity.userId, reservationId);
        const watermark = await unavailableTextWatermarkVerifier.verify(validation.restoredText);
        logEvent("credit_commit", { requestId: context.requestId, userIdHash: subject, operationId: parsed.operationId, credits: cost });
        logEvent("transform_success", {
          requestId: context.requestId,
          userIdHash: subject,
          operationId: parsed.operationId,
          model,
          attempts: attempt,
          intensity: parsed.intensity,
          purpose: parsed.purpose,
          latencyMs: Date.now() - context.startedAt,
        });
        const result: TransformResult = {
          version: "semantic-transform-v2",
          text: validation.restoredText,
          mode: parsed.mode,
          intensity: parsed.intensity,
          purpose: parsed.purpose,
          model,
          attempts: attempt,
          metrics: validation.metrics,
          receipt: {
            sourceWords: validation.metrics.sourceWords,
            outputWords: validation.metrics.outputWords,
            retainedPercent: validation.metrics.retainedPercent,
            wordingReplacedPercent: validation.metrics.wordingReplacedPercent,
            longestUnprotectedSharedWordRun: validation.metrics.unprotectedLongestSharedWordRun,
            protectedSpanCount: validation.metrics.protectedTotal,
            checks: validation.checks,
            model,
            attempts: attempt,
            creditsCharged: cost,
          },
          watermark,
          warnings: validation.warnings,
          billing: { operationId: parsed.operationId, reservationId, creditsCharged: cost, balanceAfter: balance.available },
        };
        return respond(apiOk(context, result as unknown as Record<string, unknown>));
      }
      retryFeedback = validation.errors.map((item) => `- ${item}`).join("\n");
    }

    await releaseReservation(identity.userId, reservationId, "validation_failed");
    logEvent("transform_validation_failure", { requestId: context.requestId, userIdHash: subject, operationId: parsed.operationId, attempts: MAX_ATTEMPTS });
    return respond(apiError(context, "validation_failed", "The edit did not pass factual-preservation checks. The credit hold was released.", 422));
  } catch {
    try { await releaseReservation(identity.userId, reservationId, "generation_failed"); } catch {}
    logEvent("model_provider_error", { requestId: context.requestId, userIdHash: subject, operationId: parsed.operationId, model, latencyMs: Date.now() - context.startedAt });
    return respond(apiError(context, "model_unavailable", "The editing service is temporarily unavailable. The credit hold was released or will expire automatically.", 503));
  }
}

import Link from "next/link";
import type { AdminRole } from "@/lib/admin/permissions";
import type { DashboardData } from "@/lib/admin/data";

const NAV=["Overview","Users","Growth","Usage","Billing","Subscriptions","FinOps","Operations","Audit","System"] as const;
const pathFor=(item:string)=>item==="Overview"?"/admin":`/admin/${item.toLowerCase()}`;
const money=(cents:number)=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(cents/100);
const microsMoney=(micros:number)=>money(Math.round(micros/10_000));
const sum=(values:number[])=>values.reduce((total,value)=>total+value,0);

function Metric({label,value,note}:{label:string;value:string|number;note?:string}){return <article className="admin-metric"><span>{label}</span><strong>{value}</strong>{note&&<small>{note}</small>}</article>;}
function Chart({title,values,suffix=""}:{title:string;values:number[];suffix?:string}){
  const max=Math.max(1,...values);
  return <section className="admin-chart" aria-label={`${title} chart`}><div className="admin-section-head"><div><p className="mono-label">UTC DAILY SERIES</p><h2>{title}</h2></div><span className="pill">{values.length?`${values.length} days`:"Awaiting first rollup"}</span></div><div className="bar-chart" aria-hidden="true">{values.length?values.map((value,index)=><i key={index} style={{height:`${Math.max(5,(value/max)*100)}%`}}/>):<div className="chart-empty">No rolled-up activity yet.</div>}</div><p className="chart-summary">{values.length?`Total: ${sum(values).toLocaleString()}${suffix}`:"The first secure rollup will populate this chart; no customer content is collected."}</p></section>;
}

export function AdminConsole({active,role,data}:{active:string;role:AdminRole;data:DashboardData}){
  const successTotal=data.successfulJobs+data.failedJobs;
  const successRate=successTotal?`${Math.round((data.successfulJobs/successTotal)*1000)/10}%`:"—";
  const netRevenue=data.testGrossRevenueCents-data.testRefundsCents;
  const contributionCents=netRevenue-Math.round(data.costMicros/10_000);
  const contributionMargin=netRevenue>0?`${Math.round((contributionCents/netRevenue)*1000)/10}%`:"—";
  const alerts=[
    data.pastDueSubscriptions>0?`${data.pastDueSubscriptions} TEST subscription payment state(s) need review.`:null,
    data.costByProvider.length===0?"No provider cost events have been recorded yet; FinOps will remain explicit about missing evidence.":null,
  ].filter((value):value is string=>Boolean(value));
  return <main id="main-content" className="admin-shell"><div className="shell">
    <header className="admin-hero"><div><p className="eyebrow">Command Center · private operations</p><h1>Evidence, not surveillance.</h1><p>Server-derived SaaS operations for growth, billing, credits, subscription state, cost, and deployment readiness. All financial figures are marked TEST while Stripe remains in test mode.</p></div><div className="admin-identity"><span className="mono-label">ACCESS</span><strong>{role}</strong><small>Private · no-store</small></div></header>
    <div className="admin-layout"><aside className="admin-nav" aria-label="Admin navigation"><p className="mono-label">COMMAND CENTER</p>{NAV.map((item)=><Link className={active===item.toLowerCase()||(item==="Overview"&&active==="overview")?"active":""} href={pathFor(item)} key={item}>{item}<span>↗</span></Link>)}</aside><section className="admin-content">
      {alerts.length>0&&<div className="admin-alerts" aria-label="Operational alerts">{alerts.map((alert)=><p key={alert}><span className="status-dot"/>{alert}</p>)}</div>}
      <AdminSection active={active} data={data} successRate={successRate} netRevenue={netRevenue} contributionMargin={contributionMargin}/>
    </section></div>
  </div></main>;
}

function AdminSection({active,data,successRate,netRevenue,contributionMargin}:{active:string;data:DashboardData;successRate:string;netRevenue:number;contributionMargin:string}){
  const day=data.daily;
  if(active==="users")return <><AdminHeading title="Users" copy="Privacy-safe identity and account evidence. Email disclosure is deliberately not part of this default view."/><div className="admin-kpis"><Metric label="Registered users" value={data.registeredUsers}/><Metric label="Anonymous guests" value={data.anonymousGuests}/><Metric label="New today" value={data.newUsersToday}/><Metric label="New 30D" value={data.newUsers30d}/></div><div className="admin-table-card"><h2>Safe user administration</h2><p>Identity counts are server-derived from Supabase Auth. Raw customer content, filenames, and files are never part of this operational view.</p></div></>;
  if(active==="growth")return <><AdminHeading title="Growth" copy="Daily registration, guest conversion, and activity are derived from Auth and privacy-safe operational records."/><div className="admin-kpis"><Metric label="DAU" value={data.dau}/><Metric label="WAU" value={data.wau}/><Metric label="MAU" value={data.mau}/><Metric label="DAU / MAU" value={data.mau?`${Math.round((data.dau/data.mau)*100)}%`:"—"}/></div><Chart title="Daily registrations" values={day.map((row)=>row.registeredUsers)}/><Chart title="Daily active operations" values={day.map((row)=>row.jobs)}/></>;
  if(active==="usage")return <><AdminHeading title="Usage" copy="No browser analytics, session replay, or content collection. Operational aggregates only."/><div className="admin-kpis"><Metric label="Jobs today" value={data.jobsToday}/><Metric label="Successful jobs" value={data.successfulJobs}/><Metric label="Failed jobs" value={data.failedJobs}/><Metric label="Success rate" value={successRate}/></div><Chart title="Operations per day" values={day.map((row)=>row.jobs)}/></>;
  if(active==="billing")return <><AdminHeading title="Billing" copy="Credit accounting remains authoritative in the FIFO ledger; financial values are Stripe TEST operational evidence."/><div className="admin-kpis"><Metric label="TEST gross revenue" value={money(data.testGrossRevenueCents)}/><Metric label="TEST refunds" value={money(data.testRefundsCents)}/><Metric label="TEST net revenue" value={money(netRevenue)}/><Metric label="Outstanding entitlement" value={data.creditsOutstanding}/><Metric label="Credits consumed" value={data.creditsConsumed}/><Metric label="Active subscriptions" value={data.activeSubscriptions}/></div><Chart title="TEST gross revenue by day" values={day.map((row)=>row.testGrossRevenueCents)} suffix="¢"/><Chart title="TEST refunds by day" values={day.map((row)=>row.testRefundsCents)} suffix="¢"/></>;
  if(active==="subscriptions")return <><AdminHeading title="Subscriptions" copy="Monthly credits are granted only from idempotent paid invoices. Existing pay-as-you-go packs remain separate but share FIFO credit lots."/><div className="admin-kpis"><Metric label="Active / trialing" value={data.activeSubscriptions}/><Metric label="Past due / unpaid" value={data.pastDueSubscriptions}/><Metric label="TEST MRR" value={money(data.testMrrCents)}/><Metric label="TEST ARR projection" value={money(data.testMrrCents*12)}/></div><div className="admin-table-card"><h2>{data.activeSubscriptions?"Subscription portfolio active":"No subscription activity yet"}</h2><p>{data.activeSubscriptions?"Current TEST MRR is derived from authoritative active/trialing subscription plan records. Invoice-paid grants remain idempotent by Stripe invoice ID.":"Subscription tracking is ready for the first Stripe TEST subscription. Billing Portal remains server-authoritative for cancellation."}</p></div></>;
  if(active==="finops")return <><AdminHeading title="FinOps" copy="Actual, estimated, manual, and confirmed-zero cost sources remain visibly distinct. No estimate is represented as an invoice."/><div className="admin-kpis"><Metric label="Current window cost" value={microsMoney(data.costMicros)}/><Metric label="TEST net revenue" value={money(netRevenue)}/><Metric label="Contribution margin" value={contributionMargin}/><Metric label="Cost / successful job" value={data.successfulJobs?microsMoney(Math.round(data.costMicros/data.successfulJobs)):"—"}/><Metric label="Providers with cost evidence" value={data.costByProvider.length}/></div><Chart title="Cost per day" values={day.map((row)=>row.costMicros)}/><div className="admin-table-card"><h2>Provider cost evidence</h2>{data.costByProvider.length?<ul>{data.costByProvider.map((cost)=><li key={cost.provider}><strong>{cost.provider}</strong><span>{microsMoney(cost.amountMicros)} · {cost.source}</span></li>)}</ul>:<p>No provider cost events yet. The console reports the absence explicitly rather than inventing cost coverage.</p>}</div></>;
  if(active==="operations")return <><AdminHeading title="Operations" copy="Health evidence and reconciliation status are server-side only. Secrets are never rendered."/><div className="admin-kpis"><Metric label="Database schema" value={data.schemaVersion}/><Metric label="Stripe mode" value="TEST"/><Metric label="Metrics generated" value={new Date(data.generatedAt).toLocaleString("en-US",{timeZone:"UTC"})+" UTC"}/></div><div className="admin-table-card"><h2>Runtime certification</h2><p>Deployment SHA and complete dependency readiness are authoritative at <code>/api/health</code> and <code>/api/readiness</code>. Scheduled reconciliation and daily rollups use server-only credentials.</p></div></>;
  if(active==="audit")return <><AdminHeading title="Audit" copy="Admin mutations record actor, request ID, result, object identifier, and safe metadata—never customer content or credentials."/><div className="admin-table-card"><h2>Privacy-safe audit log</h2><p>The database denies browser access to private audit tables, and the schema contains no raw content fields.</p></div></>;
  if(active==="system")return <><AdminHeading title="System" copy="Configuration values and secrets stay server-side. Runtime readiness is exposed only as safe configured/missing status."/><div className="admin-kpis"><Metric label="Schema version" value={data.schemaVersion}/><Metric label="Stripe mode" value="TEST"/><Metric label="Admin authorization" value="Server-side"/><Metric label="Automatic Git deploys" value="Disabled"/></div><div className="admin-table-card"><h2>Release evidence</h2><p>Use <code>/api/health</code> for the exact deployed SHA and <code>/api/readiness</code> for database and configuration readiness. The release workflow refuses deployment when Production preflight fails.</p></div></>;
  return <><AdminHeading title="Overview" copy="A ten-second operational readout. All metrics are server-derived and intentionally safe for a privacy-first product."/><div className="admin-kpis"><Metric label="Registered users" value={data.registeredUsers}/><Metric label="New users 7D" value={data.newUsers7d}/><Metric label="DAU / WAU / MAU" value={`${data.dau} / ${data.wau} / ${data.mau}`}/><Metric label="Jobs today" value={data.jobsToday}/><Metric label="Success rate" value={successRate}/><Metric label="Credits outstanding" value={data.creditsOutstanding}/><Metric label="TEST gross revenue" value={money(data.testGrossRevenueCents)}/><Metric label="TEST net revenue" value={money(netRevenue)}/><Metric label="TEST MRR" value={money(data.testMrrCents)}/><Metric label="Active subscriptions" value={data.activeSubscriptions}/><Metric label="Current cost" value={microsMoney(data.costMicros)}/><Metric label="Contribution margin" value={contributionMargin}/></div><div className="admin-grid"><Chart title="Daily registrations" values={day.map((row)=>row.registeredUsers)}/><Chart title="Operations per day" values={day.map((row)=>row.jobs)}/></div></>;
}
function AdminHeading({title,copy}:{title:string;copy:string}){return <header className="admin-section-heading"><p className="eyebrow">{title}</p><h1>{title}</h1><p>{copy}</p></header>;}

"use client";

import { useMemo, useState } from "react";
import {
  ARTIFACT_KINDS,
  createArtifactReceipt,
  type ArtifactKind,
  type ArtifactProvenanceReceipt,
  verifyArtifactReceipt,
  type ArtifactVerificationResult,
} from "@/lib/artifacts/provenance";

const SAMPLE = `# Example Agent Skill

Name: research-summarizer
Purpose: Summarize supplied evidence without inventing claims.

Instructions:
- Cite the supplied evidence.
- Preserve uncertainty.
- Do not expose credentials.
`;

function downloadJson(payload: unknown, name: string) {
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = name;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

export function ArtifactProvenanceWorkbench() {
  const [artifact, setArtifact] = useState(SAMPLE);
  const [kind, setKind] = useState<ArtifactKind>("agent-skill");
  const [name, setName] = useState("research-summarizer");
  const [version, setVersion] = useState("1.0.0");
  const [previousHash, setPreviousHash] = useState("");
  const [receipt, setReceipt] = useState<ArtifactProvenanceReceipt | null>(null);
  const [receiptJson, setReceiptJson] = useState("");
  const [verification, setVerification] = useState<ArtifactVerificationResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const blocked = useMemo(() => receipt?.hygiene.status === "blocked", [receipt]);

  async function generate() {
    setError(null);
    setVerification(null);
    try {
      const next = await createArtifactReceipt(artifact, {
        kind,
        artifactName: name,
        artifactVersion: version,
        previousArtifactHash: previousHash || undefined,
      });
      setReceipt(next);
      setReceiptJson(JSON.stringify(next, null, 2));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Could not create the provenance receipt.");
    }
  }

  async function verify() {
    setError(null);
    try {
      const parsed = JSON.parse(receiptJson) as ArtifactProvenanceReceipt;
      if (parsed.version !== "artifact-provenance-v1" || typeof parsed.receiptHash !== "string") {
        throw new Error("Receipt is not an artifact-provenance-v1 receipt.");
      }
      setVerification(await verifyArtifactReceipt(artifact, parsed));
    } catch (cause) {
      setVerification(null);
      setError(cause instanceof Error ? cause.message : "Could not verify this receipt.");
    }
  }

  return <section className="artifact-provenance-section" aria-label="Artifact provenance workbench">
    <div className="section-heading">
      <div>
        <p className="eyebrow">Artifact provenance</p>
        <h2>Hash the artifact. Verify the receipt.</h2>
        <p>Create local SHA-256 identity and self-hashed receipts for prompts, agent skills, configuration, JSON artifacts, and other AI assets. Optional previous hashes form an explicit version chain.</p>
      </div>
      <span className="pill local-pill">Local · no account</span>
    </div>

    <div className="artifact-grid">
      <div className="panel">
        <div className="panel-heading"><div><p className="eyebrow">Artifact</p><h2>Canonical identity</h2></div><span className="pill">SHA-256</span></div>
        <div className="artifact-controls">
          <label>Artifact kind
            <select value={kind} onChange={(event) => { setKind(event.target.value as ArtifactKind); setReceipt(null); }}>
              {ARTIFACT_KINDS.map((item) => <option value={item} key={item}>{item}</option>)}
            </select>
          </label>
          <label>Name<input value={name} onChange={(event) => setName(event.target.value)} placeholder="optional" /></label>
