import { FormEvent, useState } from "react";

export function ContactMailto({ supportEmail }: { supportEmail?: string | null }) {
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  function submit(event: FormEvent) {
    event.preventDefault();
    if (!supportEmail) return;
    const href = `mailto:${supportEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(message)}`;
    window.location.href = href;
  }
  return <form className="panel contact-form" onSubmit={submit}>
    <div className="panel-heading"><div><p className="eyebrow">Private handoff</p><h2>Open a draft in your email app.</h2></div><span className="pill">mailto only</span></div>
    <label>Subject<input required maxLength={160} value={subject} onChange={event => setSubject(event.target.value)} placeholder="Billing, privacy, account data…" /></label>
    <label>Message<textarea required maxLength={5_000} value={message} onChange={event => setMessage(event.target.value)} placeholder="Write the message that should go into your email client…" /></label>
    <div className="actions"><button className="primary" type="submit" disabled={!supportEmail}>Send message</button></div>
    <div className="trust-note"><span className="status-dot"/><div><strong>No contact POST endpoint.</strong><p>This form does not send or store the message in Provenance Cleaner. It only opens a draft in your email client.{!supportEmail ? " A production support address still needs to be configured." : ""}</p></div></div>
  </form>;
}

